-- Operator-only single SELECT extracted from the source-owned S14 Archive
-- LOCAL-ONLY candidate preflight, plus owner/SECURITY DEFINER checks.
-- Must never run from CI or browser tests. No application rows, secrets, or function bodies.
WITH wanted(kind,group_name,identity) AS (VALUES ('relation','core-parent','public.editions'),('relation','core-parent','public.shows'),('relation','core-parent','public.studio2_edition_runtime'),('relation','core-parent','public.studio2_result_operations'),('relation','core-parent','public.studio2_organizer_tasks'),('relation','core-parent','public.admin_notifications'),('relation','core-parent','public.notification_deliveries'),('relation','core-parent','public.studio2_operation_receipts'),('relation','core-parent','public.studio2_contest_events'),('relation','core-parent','private.v3_domain_events'),('relation','core-parent','private.v3_domain_event_outbox'),('relation','core-parent','public.studio2_next_in_line_windows'),('relation','core-parent','public.next_in_line_responses'),('relation','core-parent','public.studio2_eligibility_overrides'),('relation','core-parent','public.televoting_round_bindings'),('relation','core-parent','televoting.rounds'),('relation','runtime-parent','private.v3_result_versions'),('relation','runtime-parent','public.studio2_show_publication_controls'),('relation','runtime-parent','public.submission_rounds'),('relation','runtime-parent','public.submissions'),('relation','runtime-parent','public.studio2_confirmation_requirements'),('relation','runtime-parent','public.internal_entries'),('relation','runtime-parent','public.national_finals'),('relation','runtime-parent','public.national_final_entries'),('relation','runtime-parent','public.next_in_line_submissions'),('relation','runtime-parent','public.entries'),('relation','runtime-parent','public.participants'),('relation','runtime-parent','public.studio2_media_asset_reviews'),('relation','runtime-parent','public.results'),('relation','runtime-parent','public.voters'),('relation','runtime-parent','public.jury_votes'),('relation','runtime-parent','public.jury_ballot_statuses'),('relation','runtime-parent','public.jury_ballot_submissions'),('relation','runtime-parent','public.jury_voting_windows'),('relation','runtime-parent','public.televote_votes'),('relation','runtime-parent','televoting.round_countries'),('relation','runtime-parent','televoting.round_entries'),('relation','runtime-parent','televoting.round_results'),('relation','runtime-parent','televoting.vote_submissions'),('relation','runtime-parent','televoting.vote_entries'),('relation','runtime-parent','televoting.televote_aggregations'),('relation','runtime-parent','televoting.televote_aggregation_sources'),('relation','runtime-parent','televoting.televote_aggregation_participants'),('relation','runtime-parent','televoting.combined_televote_results'),('relation','runtime-parent','televoting.combined_televote_component_results'),('function','original-helper','private.studio2_reconcile_all_organizer_tasks(uuid)'),('function','original-helper','private.studio2_prune_stale_task_notifications(uuid)'),('function','original-helper','public.studio2_transition_edition_v2(uuid,text,text,uuid)'),('function','original-helper','private.studio2_request_is_service_role()'),('function','required-runtime','private.studio2_claim_operation(uuid,text,uuid,text,text,jsonb,jsonb)'),('function','required-runtime','private.studio2_complete_operation(uuid,jsonb)'),('function','required-runtime','private.studio2_default_subsystems(text)'),('function','required-runtime','private.studio2_normalise_publication_config(jsonb)'),('function','required-runtime','private.studio2_reconcile_confirmation_requirement_tasks(uuid)'),('function','required-runtime','private.studio2_reconcile_confirmation_sync_tasks()'),('function','required-runtime','private.studio2_reconcile_jury_ballot_review_tasks(uuid)'),('function','required-runtime','private.studio2_reconcile_organizer_tasks(uuid)'),('function','required-runtime','private.studio2_reconcile_organizer_tasks_operational(uuid)'),('function','required-runtime','private.studio2_reconcile_organizer_tasks_truth(uuid)'),('function','required-runtime','private.studio2_reconcile_permission_approval_tasks()'),('function','required-runtime','private.studio2_reconcile_system_job_tasks()'),('function','required-runtime','private.studio2_repair_jury_missing_ballot_tasks(uuid)'),('function','required-runtime','private.studio2_sync_task_notifications(uuid)'),('function','required-runtime','private.studio2_task_recipient_eligible(uuid,uuid)'),('function','required-runtime','private.studio2_transition_risk(text,text)'),('function','required-runtime','private.v3_emit_domain_event(text,text,text,bigint,uuid,uuid,uuid,jsonb,integer,text[])'),('function','required-runtime','private.v3_publication_result_version_release_ready(uuid,bigint)'),('function','required-runtime','public.studio2_access_allowed(text,uuid,boolean)'),('function','required-runtime','public.studio2_complete_domain_event_delivery(uuid,text,text,jsonb)'),('function','required-runtime','public.studio2_transition_edition_v2(uuid,text,text,uuid)'),('function','must-be-absent-new','private.v3_resolve_archived_edition_workflow_tasks(uuid)'),('function','must-be-absent-new','private.v3_reconcile_resolved_task_notifications(uuid)'),('function','must-be-absent-new','private.v3_project_resolved_task_delivery_state()'),('function','must-be-absent-new','private.v3_guard_archive_runtime_transition()'),('function','must-be-absent-new','private.v3_edition_final_results_ready(uuid)'),('function','must-be-absent-new','public.studio2_transition_edition_v3(uuid,text,text,uuid,bigint,uuid,text)'),('function','must-be-absent-new','private.studio2_transition_edition_v3(uuid,text,text,uuid,bigint,uuid,text)'),('function','must-be-absent-new','public.studio2_process_edition_domain_event(uuid,text,text)'),('function','must-be-absent-new','private.v3_archive_task_type_is_current_workflow(text)'),('function','must-be-absent-new','private.v3_guard_archived_edition_task_resurrection()'),('function','must-be-absent-new','private.v3_sync_archived_edition_legacy_status()'),('function','must-be-absent-new','private.v3_guard_archived_legacy_edition_status()'),('function','must-be-absent-new','private.v3_archived_workflow_row_edition(jsonb)'),('function','must-be-absent-new','private.v3_guard_archived_edition_workflow_write()'),('function','must-be-absent-new','private.v3_arm_archive_runtime_transition_gate(uuid)'),('function','must-be-absent-new','private.v3_televote_row_solaris_editions(text,jsonb)'),('function','must-be-absent-new','private.v3_guard_archived_televote_write()'),('function','must-be-absent-new','private.v3_archive_task_reconciliation_gate_active(uuid)')),
catalog AS (SELECT kind,group_name,identity,
 CASE WHEN kind='relation' THEN to_regclass(identity) IS NOT NULL
      ELSE to_regprocedure(identity) IS NOT NULL END AS exists_now FROM wanted)
SELECT statement_timestamp() AS observed_at,
 current_setting('server_version_num') AS postgres_version_num,
 (SELECT jsonb_agg(jsonb_build_object('kind',kind,'group',group_name,'identity',identity,'present',exists_now) ORDER BY group_name,identity) FROM catalog) AS identities,
 (SELECT jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'definition_md5',md5(pg_get_functiondef(p.oid))) ORDER BY p.oid::regprocedure::text)
  FROM pg_proc p WHERE p.oid IN (to_regprocedure('private.studio2_reconcile_all_organizer_tasks(uuid)'),to_regprocedure('private.studio2_prune_stale_task_notifications(uuid)'))) AS upstream_security_definers,
 (SELECT COUNT(*) FROM pg_trigger tr WHERE NOT tr.tgisinternal AND tr.tgname=ANY(array[
 'v3_guard_archive_runtime_transition','v3_guard_archive_runtime_update','v3_guard_archive_runtime_insert','v3_guard_archive_runtime_delete',
 'v3_guard_archived_edition_task_resurrection','v3_project_resolved_task_delivery_state','v3_guard_archived_edition_workflow_write',
 'v3_guard_archived_televote_write','v3_sync_archived_edition_legacy_status','v3_guard_archived_legacy_edition_status'])) AS new_archive_trigger_collisions,
 (SELECT COUNT(*) FROM pg_class c WHERE c.oid IN (to_regclass('private.v3_archive_runtime_transition_gates'),to_regclass('private.v3_archive_task_reconciliation_gates'))) AS private_gate_collisions,
 to_regclass('private.v3_migration_contracts') IS NOT NULL AS s13_registry_table_present,
 to_regprocedure('public.v3_register_migration_contract(text,integer,text,boolean,text,text)') IS NOT NULL AS s13_registry_rpc_present;
